import java.util.*; public class BellmanFord { public static Map<String,Integer> run(Map<String,Map<String,Integer>>g,String s){Map<String,Integer>d=new HashMap<>();for(String k:g.keySet())d.put(k,Integer.MAX_VALUE);d.put(s,0);for(int i=1;i<g.size();i++)for(String u:g.keySet())for(var e:g.get(u).entrySet())if(d.get(u)!=Integer.MAX_VALUE)d.put(e.getKey(),Math.min(d.get(e.getKey()),d.get(u)+e.getValue()));return d;} }